    '약관 PDF 는 <b>이 브라우저에만</b> 쌓습니다 — 앱의 약관 분석기가 그렇게 만들어져 있습니다.',
    '고객에게 캡처를 보낼 때도 <b>필요한 조문 한 곳</b>만, 회사·상품·판을 함께 적어 보내십시오.',
    '조문을 옮겨 적을 때 <b>줄이거나 고치지 않습니다.</b> 줄인 문장은 나중에 다른 뜻이 됩니다.',
